import{digest}from"../lib/helpers.js";import{encode as b64u}from"../util/base64url.js";import{JOSENotSupported,JWKInvalid}from"../util/errors.js";import{encode}from"../lib/buffer_utils.js";import{isKeyLike}from"../lib/is_key_like.js";import{isJWK}from"../lib/type_checks.js";import{exportJWK}from"../key/export.js";import{invalidKeyInput}from"../lib/invalid_key_input.js";const check=(e,r)=>{if("string"!=typeof e||!e)throw new JWKInvalid(`${r} missing or invalid`)};export async function calculateJwkThumbprint(e,r){let t,a;if(isJWK(e))t=e;else{if(!isKeyLike(e))throw new TypeError(invalidKeyInput(e,"CryptoKey","KeyObject","JSON Web Key"));t=await exportJWK(e)}if(r??="sha256","sha256"!==r&&"sha384"!==r&&"sha512"!==r)throw new TypeError('digestAlgorithm must one of "sha256", "sha384", or "sha512"');switch(t.kty){case"AKP":check(t.alg,'"alg" (Algorithm) Parameter'),check(t.pub,'"pub" (Public key) Parameter'),a={alg:t.alg,kty:t.kty,pub:t.pub};break;case"EC":check(t.crv,'"crv" (Curve) Parameter'),check(t.x,'"x" (X Coordinate) Parameter'),check(t.y,'"y" (Y Coordinate) Parameter'),a={crv:t.crv,kty:t.kty,x:t.x,y:t.y};break;case"OKP":check(t.crv,'"crv" (Subtype of Key Pair) Parameter'),check(t.x,'"x" (Public Key) Parameter'),a={crv:t.crv,kty:t.kty,x:t.x};break;case"RSA":check(t.e,'"e" (Exponent) Parameter'),check(t.n,'"n" (Modulus) Parameter'),a={e:t.e,kty:t.kty,n:t.n};break;case"oct":check(t.k,'"k" (Key Value) Parameter'),a={k:t.k,kty:t.kty};break;default:throw new JOSENotSupported('"kty" (Key Type) Parameter missing or unsupported')}const i=encode(JSON.stringify(a));return b64u(await digest(r,i))}export async function calculateJwkThumbprintUri(e,r){r??="sha256";const t=await calculateJwkThumbprint(e,r);return`urn:ietf:params:oauth:jwk-thumbprint:sha-${r.slice(-3)}:${t}`}